def _raise_for_github_status(response: Any) -> None:
    """Raise a bounded error that preserves GitHub's useful API message."""
    try:
        response.raise_for_status()
    except httpx.HTTPStatusError as exc:
        try:
            payload = response.json()
        except (TypeError, ValueError):
            payload = getattr(response, "text", "")
        message = payload.get("message", "") if isinstance(payload, dict) else str(payload)
        message = str(message).strip()[:800]
        if message:
            raise RuntimeError(f"{exc}; GitHub response: {message}") from exc
        raise

