def application_evidence_note() -> str:
    notes = []
    for item in source_usage[:4]:
        package = item["package"]
        locations = item.get("locations", [])
        production_usage = sorted({str(location.get("evidence_classification")) for location in locations
                                   if location.get("area") == "application"
                                   and location.get("evidence_classification") in {"direct_import", "api_usage"}})
        test_usage = sorted({str(location.get("evidence_classification")) for location in locations
                             if location.get("area") == "tests"})
        usage = ", ".join(production_usage) if production_usage else "no production usage established"
        if test_usage:
            usage += "; test evidence " + ", ".join(test_usage)
        reachability = ", ".join(sorted({
            str(record.get("status", "unknown")) for record in item.get("vulnerability_reachability", [])
        })) or "unknown"
        relationship = item.get("dependency_relationship", item.get("relationship", "unknown"))
        notes.append(f"{package}: dependency graph {relationship}; production source evidence {usage}, reachability {reachability}")
    return "; ".join(notes)

