def chunk_source(
    relative_path: str, source: str, *, parser_cache_dir: str | Path | None = None,
) -> list[dict[str, Any]]:
    """Create safe, source-located chunks for Python and JS/TS files."""
    if not _safe_relative_path(relative_path) or not source.strip():
        return []
    suffix = Path(relative_path).suffix.lower()
    if suffix == ".py":
        chunks = _python_chunks(relative_path, source)
    else:
        chunks = _tree_sitter_chunks(relative_path, source, parser_cache_dir)
        if not chunks:
            chunks = _javascript_fallback_chunks(relative_path, source)
    return chunks or _line_chunks(relative_path, source)

def test_javascript_chunking_preserves_common_declaration_boundaries():
